const chatId = String($json.message?.chat?.id || '');
const text = ($json.message?.text || '').trim();
const m = text.match(/^\/familyweekly\s+(\S+)\s+([\s\S]+)/i);

if (!chatId) throw new Error('No chat id in Telegram payload');

if (!m) {
  return {
    json: {
      chatId,
      sendTo: '',
      subject: '',
      body: '',
      ackText: 'Usage: /familyweekly <toEmail> <weekLabel>'
    }
  };
}

const toEmail = m[1];
const weekLabel = m[2].trim();

return {
  json: {
    chatId,
    sendTo: toEmail,
    subject: `Family weekly update - ${weekLabel}`,
    body: [
      `Weekly family update (${weekLabel})`,
      '',
      'School: TODO',
      'Activities: TODO',
      'Meals/groceries: TODO',
      'Appointments: TODO',
      '',
      'Generated from n8n family workflow draft.'
    ].join('\n'),
    ackText: `Weekly family update prepared for ${toEmail}`
  }
};
